public class Isleapyear {

    public boolean isleapyear( int aYear )
    {
    	// divisible by 4
    	// divisible by 4 and not 100  (1900 is not a leap year)
    	// divisible by 4 and not 100 unless divisible by 400

    	return (aYear % 4 == 0) && ((aYear % 100 != 0) || (aYear % 400 == 0));
    }
