public class MININTINDEX {

	public static int minIntIndex(int... d) {
		if((d == null) || (d.length == 0)) {
			throw new IllegalArgumentException("d cannot be null");
		}
		int index = 0;
		for(int x = 0; x < d.length; x++) {
			if(d[x] < d[index]) {
				index = x;
			}
		}
		return index;
	}
},5

